/* ---------- Activity heatmap ---------- */
.hmx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:10px}
.hmx-h{display:flex;align-items:center;justify-content:space-between;gap:10px}
.hmx-h>div:first-child{display:flex;flex-direction:column;font-size:13.5px}
.hmx-h b{font-weight:500}
.hmx-st{font-size:12px}
.hmx-sg button{font-size:12px;height:26px;padding:0 9px}
/* the day names, the cells and the hour names sit in one grid, so the hour names line up with the cells; on a phone the
   grid scrolls sideways (below) and the day names stay put */
.hmx-sc{display:grid;grid-template-columns:auto minmax(0,1fr);gap:6px}
.hmx-days{display:grid;grid-template-rows:repeat(7,1fr);gap:3px;font-size:10px}
.hmx-days span{display:flex;align-items:center;height:100%}
.hmx-grid{display:grid;grid-template-columns:repeat(24,minmax(0,1fr));gap:3px;min-width:0}
.hmx-grid i{aspect-ratio:1;border-radius:3px;background:color-mix(in srgb,var(--dm-accent) calc(var(--dm-a) * 100%),var(--dm-chip));transition:background .5s var(--dm-ease),transform .2s;max-width:100%}
@media (hover:hover) and (pointer:fine){.hmx-grid i:hover{transform:scale(1.35);box-shadow:0 0 0 1.5px var(--dm-surface);position:relative;z-index:1}}
.hmx-f{grid-column:2;display:grid;grid-template-columns:repeat(4,1fr);font-size:10.5px}
.hmx-f .x{display:none}
/* phones, and narrow cards: half the day at a time in bigger cells, scrolled sideways by touch or trackpad, starting at the
   latest hours. The edge the grid runs on past fades out, and the hour names come every three hours */
.hmx{container-type:inline-size}
@container (max-width:400px){
  .hmx-sc{grid-template-columns:34px calc((100cqw - 34px) * 2);column-gap:0;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:none;scroll-snap-type:x proximity;scroll-padding-left:34px;
    --dm-fl:0px;--dm-fr:0px;-webkit-mask-image:linear-gradient(to right,#000 34px,transparent 34px,#000 calc(34px + var(--dm-fl)),#000 calc(100% - var(--dm-fr)),transparent);mask-image:linear-gradient(to right,#000 34px,transparent 34px,#000 calc(34px + var(--dm-fl)),#000 calc(100% - var(--dm-fr)),transparent)}
  .hmx-sc::-webkit-scrollbar{display:none}
  .hmx-sc.ml{--dm-fl:16px}.hmx-sc.mr{--dm-fr:16px}
  .hmx-days{position:sticky;left:0;z-index:2;background:var(--dm-surface);gap:4px;padding-right:6px;font-size:10.5px}
  /* and the corner under the day names covers the hour names as they scroll past */
  .hmx-sc::after{content:"";grid-row:2;grid-column:1;position:sticky;left:0;z-index:2;background:var(--dm-surface)}
  .hmx-grid{gap:4px}
  .hmx-grid i{border-radius:calc(4px * var(--dm-rk));scroll-snap-align:start}
  .hmx-f{grid-template-columns:repeat(8,1fr)}
  .hmx-f .x{display:block}
}
.hmx-lg{align-self:flex-end;display:flex;align-items:center;gap:3px;font-size:10.5px}
.hmx-lg i{width:9px;height:9px;border-radius:2px;background:color-mix(in srgb,var(--dm-accent) calc(var(--dm-a) * 100%),var(--dm-chip))}

DM.def('activity-heatmap', (r, c) => {
  const DAYS = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
  const grid = $('.hmx-grid', r), st = $('.hmx-st', r);
  const gen = (who) => { const a = []; for (let d = 0; d < 7; d++) for (let h = 0; h < 24; h++){
    let v = who === 'agent' ? (h >= 1 && h <= 5 ? .75 : h >= 9 && h <= 18 ? .45 : .15) : (h >= 9 && h <= 18 ? .65 : h >= 19 && h <= 22 ? .2 : .03);
    if (d >= 5) v *= who === 'agent' ? .8 : .2; if (who === 'agent' && d === 0 && h === 9) v = 1;
    v = Math.max(0, Math.min(1, v + (Math.sin(d * 7.1 + h * 3.3) * .18))); a.push(v); } return a; };
  const D = { agent:gen('agent'), team:gen('team') };
  grid.innerHTML = Array.from({ length:168 }, () => '<i style="--dm-a:0"></i>').join('');
  const cells = $$('i', grid);
  function draw(w){ cells.forEach((el, i) => { const d = Math.floor(i / 24), h = i % 24, v = D[w][i]; c.later((h + d) * 14, () => el.style.setProperty('--dm-a', (v * .9).toFixed(2)));
    const hr = (h % 12 || 12) + (h < 12 ? 'am' : 'pm'); el.dataset.tip = `${DAYS[d]} ${hr}: ${Math.round(v * (w === 'agent' ? 40 : 25))} ${w === 'agent' ? 'runs' : 'edits'}`; });
    swap(st, w === 'agent' ? 'Busiest overnight, when the queue runs' : 'Busiest 10am to 4pm on weekdays'); }
  seg($('.hmx-sg', r), draw);
  c.later(240, () => draw('agent'));
  // on a phone the grid scrolls sideways: it starts at the latest hours, and fades out on whichever side has more to see
  const sc = $('.hmx-sc', r);
  const edges = () => { const m = sc.scrollWidth - sc.clientWidth; sc.classList.toggle('ml', m > 1 && sc.scrollLeft > 1); sc.classList.toggle('mr', m > 1 && sc.scrollLeft < m - 1); };
  // it stays on the latest hours as the card settles its size, until the person scrolls it themselves
  let moved = false;
  const fit = () => { if (!moved) sc.scrollLeft = sc.scrollWidth; edges(); };
  c.on(sc, 'scroll', edges, { passive:true });
  ['pointerdown', 'wheel', 'touchstart', 'keydown'].forEach(e => c.on(sc, e, () => { moved = true; }, { passive:true }));
  const ro = new ResizeObserver(fit); ro.observe(sc); ro.observe(grid); c.offs.push(() => ro.disconnect());
});
